/* @lc app=leetcode id=3318 lang=kotlin */ class Solution { fun key(c: Int, v: Int): Long = (c.toLong() shl 32) or v.toLong() fun mvUp(top: java.util.TreeSet<Long>, rest: java.util.TreeSet<Long>, sm: LongArray, k: Long) = rest.remove(k).also { top.add(k) }.also { sm[0] += (k shr 32) * (k and 0xFFFFFFFFL) } fun mvDown(top: java.util.TreeSet<Long>, rest: java.util.TreeSet<Long>, sm: LongArray, k: Long) = top.remove(k).also { rest.add(k) }.also { sm[0] -= (k shr 32) * (k and 0xFFFFFFFFL) } fun fix(top: java.util.TreeSet<Long>, rest: java.util.TreeSet<Long>, sm: LongArray, x: Int) = generateSequence(0) { if (top.size > x) mvDown(top, rest, sm, top.first()).let { 0 } else if (top.size < x && rest.isNotEmpty()) mvUp(top, rest, sm, rest.last()).let { 0 } else if (rest.isNotEmpty() && top.isNotEmpty() && top.first() < rest.last()) mvDown(top, rest, sm, top.first()).let { mvUp(top, rest, sm, rest.last()) }.let { 0 } else null }.count() fun upd(cnt: HashMap<Int, Int>, top: java.util.TreeSet<Long>, rest: java.util.TreeSet<Long>, sm: LongArray, x: Int, v: Int, d: Int) = (cnt[v] ?: 0).let { old -> (old + d).let { nw -> (if (old > 0) key(old, v).let { k -> if (top.remove(k)) sm.set(0, sm[0] - old.toLong() * v) else rest.remove(k) } else Unit).let { cnt[v] = nw }.let { if (nw > 0) rest.add(key(nw, v)) }.let { fix(top, rest, sm, x) } } } fun findXSum(nums: IntArray, k: Int, x: Int): IntArray = HashMap<Int, Int>().let { cnt -> java.util.TreeSet<Long>().let { top -> java.util.TreeSet<Long>().let { rest -> LongArray(1).let { sm -> nums.indices.mapNotNull { i -> upd(cnt, top, rest, sm, x, nums[i], 1).let { if (i >= k) upd(cnt, top, rest, sm, x, nums[i - k], -1) }.let { if (i >= k - 1) sm[0].toInt() else null } }.toIntArray() } } } } }